style.xsl:text:
      @media print {
        #pageHeader {
          position: relative !important;
        }

        #pageHeader svg text,
        #pageHeader svg #RectangleV
        {
          fill: black !important;
        }
      }

			/* 'GolosWebTextRegular'; */
			@font-face {
				font-family: GolosText;
				src: url(data:application/octet-stream;base64,);
				src:
					url('data:application/octet-stream;base64,?#iefix') format('embedded-opentype'),
					url(data:application/octet-stream;base64,) format('woff2'),
					url(data:application/octet-stream;base64,) format('woff'),
					url(data:application/octet-stream;base64,) format('truetype');
				font-weight: normal;
				font-style: normal;
				font-stretch: normal;
			}

			/* 'GolosWebTextMedium' */
			@font-face {
				font-family: GolosText;
				src: url(data:application/octet-stream;base64,);
				src:
					url('data:application/octet-stream;base64,?#iefix') format('embedded-opentype'),
					url(data:application/octet-stream;base64,) format('woff2'),
					url(data:application/font-woff;base64,) format('woff'),
					url(data:application/octet-stream;base64,) format('truetype');
				font-weight: 500;
				font-style: normal;
				font-stretch: normal;
			}

			/* 'GolosWebTextBold' */
			@font-face {
				font-family: GolosText;
				src: url(data:application/octet-stream;base64,);
				src:
					url('data:application/octet-stream;base64,?#iefix') format('embedded-opentype'),
					url(data:application/octet-stream;base64,) format('woff2'),
					url(data:application/font-woff;base64,) format('woff'),
					url(data:application/octet-stream;base64,) format('truetype');
				font-weight: bold;
				font-style: normal;
				font-stretch: normal;
			}

body {
	padding: 0 !important;
	overflow-x: hidden;
	overflow-y: auto !important;
	background: #fff;
	height: 100%;
	margin: 0;
}

.app-main-layout {
	width: 1024px;
	margin: 0 auto;
	display: block;
	padding: 0 40px;
	box-sizing: border-box;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
}

.app-header {
	position: fixed;
	display: block;
	top: 0;
	left: 0;
	width: 100%;
	box-sizing: border-box;
	height: 78px;
	background: #1e3686;
	z-index: 200;
}

.background {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 78px;
	background-color: #1e3686;
}

.app-top-nav-menu {
	display: block;
	position: relative;
	max-width: 1024px;
	margin: 0 auto;
	padding: 0 40px;
	box-sizing: border-box;
	transition: padding .5s;
}

.nav {
	position: relative;
	float: left;
	width: 100%;
	vertical-align: middle;
	line-height: 78px;
	max-height: 78px;
}

.app-title {
	margin: 118px 0px 40px 0px;

	font-family: GolosText;
	font-size: 32px;
	font-stretch: normal;
	font-style: normal;
	letter-spacing: normal;

	font-weight: bold;
	line-height: 1.16;
	color: #333333;
}

.work-area {
	display: flex;
	flex-direction: row;
	justify-content: space-between;
	margin-top: 22px;
}

.content-area>.content-area-expert-num {
	font-size: 24px;
	font-weight: 500;
	line-height: 1.33;
}

.content-area>.content-area-info {
	display: flex;
	flex-direction: row;
	margin-top: 22px;
}

.content-area-info>.content-area-title {
	display: flex;
	flex-direction: column;

	margin-bottom: 15px;
}

.content-area-title>.content-area-title-item {
	margin-bottom: 15px;
	font-family: GolosText;
	font-size: 15px;
	font-weight: 500;
	font-stretch: normal;
	font-style: normal;
	line-height: 1.07;
	letter-spacing: normal;
	color: #707e9d;
}

.content-area-info>.content-area-val {
	display: flex;
	flex-direction: column;

	margin-bottom: 15px;
}

.content-area-val>.content-area-val-item {
	margin: 0 0 9px 68px;
	font-family: GolosText;
	font-size: 15px;
	font-weight: normal;
	font-stretch: normal;
	font-style: normal;
	line-height: 1.4;
	letter-spacing: normal;
	color: #333333;
}

.control-area {
	margin-top: 40px;
}

.pageContent {
	/* margin-top: 78px; */
	position: relative;
	margin: 0 auto;

	/* min-height: calc(100vh - 78px); */
	clear: both;
}

app-footer {
	display: flex;
	position: relative;

	flex-wrap: wrap;

	justify-content: space-between;
	padding: 40px 80px 43px 80px;
	transition: padding .5s;
}

input.button {
	width: 300px;
	height: 48px;
	border-radius: 4px;
	background-color: #1e3686;
	font-family: GolosText;
	font-size: 15px;
	font-weight: normal;
	font-stretch: normal;
	font-style: normal;
	line-height: 1;
	letter-spacing: normal;
	text-align: center;
	color: #ffffff;
	border: none;
	outline: none;
	cursor: pointer;
}

input.button:active {
	transform: translateY(1px);
}

.right-area {
	margin-top: 25px;
}

.right-area>a>img {
	width: 200px;
	height: 200px;
}

.footer-content {
	display: flex;
	margin: 60px 0 40px 0;
	flex-wrap: wrap;
	padding: 0 20px;
	font-family: GolosText;
	font-size: 14px;
	color: #12235c;
	border: solid 1px #000000;
}

.footer-content>.footer-content-item {
	width: calc(50% - 40px);
	/* height: 190px; */
	margin: 20px;
	padding: 20px 40px;
	border: solid 2px #1e3686;
	display: flex;
	flex-direction: column;
	box-sizing: border-box;
}

.footer-content-item>.footer-content-item-title {
	text-align: center;
}

.footer-content-item-tab table {
	width: 100%;
	margin: 0;
	border-collapse: collapse;
}

.footer-content-item-tab td:last-child {
	word-break: break-all;
	word-break: break-word;
}

.footer-content-item-tab td {
	font-family: GolosText;
	border: none;
	vertical-align: top;
	padding: 10px 0 0 0;
	font-size: 14px;
	color: #12235c;
}

.footer-content-item-tab td:first-child {
	padding: 10px 10px 0 0;
}

.footer-content-item>.footer-content-item-tab {
	display: flex;
	flex-direction: row;
	margin-top: 30px;
}

#conclusionBody>div {
	position: relative !important;
	width: auto !important;
	left: auto !important;
	margin-left: 0px !important;
}

script.xsl:text:

	function convertXml(){
		var parser = new DOMParser();
		var doc = parser.parseFromString(document.getElementById("conclusionBody").innerHTML, "text/html");

		document.getElementById("conclusionBody").innerHTML = doc.documentElement.innerText;

		document.getElementById("conclusionBody").style.display = "block";
	};

  var Base64Binary = {
	_keyStr : "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=",

	decodeArrayBuffer: function(input) {
		  var bytes = (input.length/4) * 3;
		  var ab = new ArrayBuffer(bytes);
		  this.decode(input, ab);

		  return ab;
	  },

	  removePaddingChars: function(input){
		  var lkey = this._keyStr.indexOf(input.charAt(input.length - 1));
		  if(lkey == 64){
			  return input.substring(0,input.length - 1);
		  }
		  return input;
	  },

	  decode: function (input, arrayBuffer) {
		  input = this.removePaddingChars(input);
		  input = this.removePaddingChars(input);

		  var bytes = parseInt((input.length / 4) * 3, 10);

		  var uarray;
		  var chr1, chr2, chr3;
		  var enc1, enc2, enc3, enc4;
		  //var i = 0;
		  var j = 0;

		  if (arrayBuffer)
			  uarray = new Uint8Array(arrayBuffer);
		  else
			  uarray = new Uint8Array(bytes);

		  input = input.replace(/[^A-Za-z0-9\+\/\=]/g, "");

	  for (i=0; i<bytes; i+=3) {                
			  enc1 = this._keyStr.indexOf(input.charAt(j++));
			  enc2 = this._keyStr.indexOf(input.charAt(j++));
			  enc3 = this._keyStr.indexOf(input.charAt(j++));
			  enc4 = this._keyStr.indexOf(input.charAt(j++));

			  chr1 = (enc1 << 2) | (enc2 >> 4);
			  chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
			  chr3 = ((enc3 & 3) << 6) | enc4;

			  uarray[i] = chr1;			
			  if (enc3 != 64) uarray[i+1] = chr2;
			  if (enc4 != 64) uarray[i+2] = chr3;
		  }

		  return uarray;	
	  }
  };

  function downloadFile(fileName, fileContentBase64) {
	var byteArray = Base64Binary.decodeArrayBuffer(fileContentBase64);
	var blobObject = new Blob([byteArray], { type: 'base64;charset=utf-8;' });

	if (window.navigator.msSaveBlob) {             
	  window.navigator.msSaveBlob(blobObject, fileName);
	}
	else {                 
	  var data = window.URL.createObjectURL(blobObject, {type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document;charset=utf-8;"});
	  var a = document.getElementById("donwloadLink");
	  a.setAttribute('download', fileName);
	  a.setAttribute('href', data);
	  a.target="_self" ;
	  a.click();
	}  

	event.preventDefault();
	return false;
  };

  function decodeBase64(fileContentBase64, fileSize, type, onload) {

	var byteArray = Base64Binary.decodeArrayBuffer(fileContentBase64);
	byteArray = byteArray.slice(0,fileSize);
	var blobObject = new Blob([byteArray], { type: 'base64;charset=utf-8;' });

	var reader = new FileReader();
	reader.onload = function() {
		onload(reader.result, type);
	}
	reader.readAsText(blobObject);
  };
